package br.com.sussmartcare.notification.infrastructure; import org.apache.kafka.common.TopicPartition; import org.springframework.context.annotation.*; import org.springframework.kafka.core.KafkaTemplate; import org.springframework.kafka.listener.*; import org.springframework.util.backoff.FixedBackOff; @Configuration public class KafkaErrorConfig{@Bean DefaultErrorHandler notificationKafkaErrorHandler(KafkaTemplate<Object,Object> template){return new DefaultErrorHandler(new DeadLetterPublishingRecoverer(template,(r,e)->new TopicPartition(r.topic()+".DLT",r.partition())),new FixedBackOff(1000L,2L));}}
